/// <summary>
/// MPJ_25205 Customer aging report DCP 15 06 2022
/// </summary
[ExtensionOf(classStr(CustAgingReportDP))]
final class METCustAgingReportDP_Extension
{
}

Method.Source:
    /// <summary>
    ///    Processes the report business logic.
    /// </summary>
    /// <remarks>
    ///    This method is used to process the report business logic that is used by the <c>CustAgingReport</c>
    ///    report.
    /// </remarks>
    public void processReport()
    {
        next processReport();

        CustBalanceList             metCustBalanceList;
        CustVendAgingProcessingTmp  metCustVendAgingProcessingTmp;
        CustVendAgingProcessingDetailsTmp metCustVendAgingProcessingDetailsTmp;
        
        QueryRun                    metQR;
        ForwardBackwardPrinting     metTmpDirection;
        boolean                     metReverseAmountsAndHeadings;
        boolean                     metIsPublicSectorScenario;

        contract = this.parmDataContract() as CustAgingReportContract;

        metQR = new QueryRun(this.parmQuery());

        if (!contract.parmZeroDate())
        {
            // When the zero date is not given then use the system session date.
            contract.parmZeroDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        }

        if (!contract.parmBalanceAsOfDate())
        {
            // When balance as of date is not given then use the max date to include all transactions.
            contract.parmBalanceAsOfDate(dateMax());
        }

        if (contract.parmAgingBuckets())
        {
            // Force layout direction to backwards,
            // the actual direction of the columns is done in the construct method of the class: CustVendBalanceList
            metTmpDirection = StatRepInterval::find(contract.parmAgingBuckets()).PrintDirection;
        }
        else
        {
            metTmpDirection = contract.parmDirection();
        }

        metReverseAmountsAndHeadings = this.METGetReverseAmountsAndHeadings(contract.parmAgingBuckets(), metTmpDirection);

        metIsPublicSectorScenario = CustBillingClassificationReportManager::isPublicSectorScenario(contract.parmBillingClassification());

        if (metIsPublicSectorScenario)
        {
            metCustBalanceList = CustVendBalanceList::construct(SysModule::Cust,
                                                                    contract.parmDateTransactionDuedate(),
                                                                    contract.parmInterval(),
                                                                    contract.parmBalanceAsOfDate(),
                                                                    contract.parmZeroDate(),
                                                                    contract.parmPayments(),
                                                                    contract.parmPeriod(),
                                                                    metTmpDirection,
                                                                    contract.parmAgingBuckets(),
                                                                    NoYes::Yes,
                                                                    contract.parmDetailed(),
                                                                    contract.parmBillingClassification(),
                                                                    contract.parmInclTransWithNoBillingClass(),
                                                                    contract.parmExcludeZeroBalanceCustomer(),
                                                                    !contract.parmPrintZeroOrNegative());
        }
        else
        {
            metCustBalanceList = CustVendBalanceList::construct(SysModule::Cust,
                                                                    contract.parmDateTransactionDuedate(),
                                                                    contract.parmInterval(),
                                                                    contract.parmBalanceAsOfDate(),
                                                                    contract.parmZeroDate(),
                                                                    contract.parmPayments(),
                                                                    contract.parmPeriod(),
                                                                    metTmpDirection,
                                                                    contract.parmAgingBuckets(),
                                                                    NoYes::Yes,
                                                                    contract.parmDetailed(),
                                                                    null,
                                                                    NoYes::No,
                                                                    contract.parmExcludeZeroBalanceCustomer(),
                                                                    !contract.parmPrintZeroOrNegative());
        }
        
        metCustBalanceList.METAgingProcessing(metQR, CustVendAgingQueryConverter::convertCustomers(metQR.query()));

        metCustVendAgingProcessingTmp       = metCustBalanceList.METGetCustVendAgingProcessingTmp();
        metCustVendAgingProcessingDetailsTmp = metCustBalanceList.METGetCustVendAgingProcessingDetailsTmp();

        //adjust column values
        CustAgingReportTmp  metCustAgingReportTmp   =   this.getCustAgingReportTmp();

        this.metUpdateFromCustTable(metCustAgingReportTmp);
        
        this.metUpdateFromCustDispute(metCustAgingReportTmp, metCustVendAgingProcessingTmp);
        
        this.metUpdateUnallocatedCash(metCustAgingReportTmp, metCustVendAgingProcessingTmp, metCustVendAgingProcessingDetailsTmp, metCustBalanceList);
        
        this.metUpdateLegalDispute(metCustAgingReportTmp);

        this.metUpdateOverDue(metCustAgingReportTmp, metCustBalanceList);

        this.metUpdateCreditLimit(metCustAgingReportTmp);

    }

    /// <summary>
    /// Processes the report business logic. copy of standard which is maked private and cant be used here
    /// </summary>
    /// <param name = "_agingBucket">aging bucket from dialog</param>
    /// <param name = "_direction">print direction from dialog</param>
    /// <returns>true or false</returns>
    public boolean metGetReverseAmountsAndHeadings(CustVendAgingBucketLookUp _agingBucket, ForwardBackwardPrinting _direction)
    {
        boolean reverseAmountsAndHeadings = false;

        if (_agingBucket == '' && _direction == ForwardBackwardPrinting::Forward)
        {
            reverseAmountsAndHeadings = true;
        }

        return reverseAmountsAndHeadings;
    }

    /// <summary>
    /// Processes the report business logic. 
    /// </summary>
    /// <param name = "_metCustAgingReportTmp">original transaction buffer</param>
    public void metUpdateFromCustTable(CustAgingReportTmp _metCustAgingReportTmp)
    {
        CustAgingReportTmp  metCustAgingReportTmp = _metCustAgingReportTmp;
        METCustTable        metCustTable;

        //1. populate METIndustryKey, METLoanValueNotDue, METCreditLimit columns. // MPJ-16249- New column creditlimit
        ttsbegin;

        update_recordset metCustAgingReportTmp
            setting
            METIndustryKey      = metCustTable.IndustryKey,
            METLoanValueNotDue  = metCustTable.LoanValueNotDue
        join AccountNum, IndustryKey, LoanValueNotDue
            from metCustTable
            where  metCustTable.AccountNum == metCustAgingReportTmp.AccountNum;

        ttscommit;
    }

    /// <summary>
    /// Processes the report business logic.
    /// </summary>
    /// <param name = "_metCustAgingReportTmp">original transaction buffer</param>
    /// <param name = "_metCustVendAgingProcessingTmp">original transaction detail buffer</param>
    public void metUpdateFromCustDispute(CustAgingReportTmp _metCustAgingReportTmp, CustVendAgingProcessingTmp  _metCustVendAgingProcessingTmp)
    {
        CustAgingReportTmp  metCustAgingReportTmp = _metCustAgingReportTmp;
        CustDispute         metCustDispute;

        //2. poulate METTotalInDispute columns
        ttsbegin;
        
        while select forupdate metCustAgingReportTmp
        {
            select  sum(AmountCur)
                from    _metCustVendAgingProcessingTmp
                where   _metCustVendAgingProcessingTmp.AccountNum == metCustAgingReportTmp.AccountNum
                
            exists join metCustDispute
                where metCustDispute.CustTrans == _metCustVendAgingProcessingTmp.transRecId
                &&    metCustDispute.Status    == CustVendDisputeStatus::Disputed;

            if(_metCustVendAgingProcessingTmp.AmountCur)
            {
                metCustAgingReportTmp.METTotalInDispute = _metCustVendAgingProcessingTmp.AmountCur;
                metCustAgingReportTmp.update();
            }
        }

        ttscommit;
    }

    /// <summary>
    /// Processes the report business logic.
    /// </summary>
    /// <param name = "_metCustAgingReportTmp">original transaction buffer</param>
    /// <param name = "_metCustVendAgingProcessingTmp">original transaction detail buffer</param>
    /// <param name = "_metCustVendAgingProcessingDetailsTmp">original transaction detail buffer</param>
    /// <param name = "_metCustBalanceList">Parameters</param>
    public void metUpdateUnallocatedCash(CustAgingReportTmp         _metCustAgingReportTmp, 
                                        CustVendAgingProcessingTmp  _metCustVendAgingProcessingTmp, 
                                        CustVendAgingProcessingDetailsTmp _metCustVendAgingProcessingDetailsTmp,
                                        CustBalanceList             _metCustBalanceList)
    {
        CustAgingReportTmp  metCustAgingReportTmp = _metCustAgingReportTmp;
        METBalanceColumn    metBalanceColumn;
        boolean             metUpdateRecord = false;
        CustTrans           metCustTrans;

        //3. populate METUnallocatedCash.
        // find unsettled payment transactions and remove value from aging bucket and add into METUnallocatedCash column
        ttsbegin;
        while select forupdate metCustAgingReportTmp  //loop each customer
        {
            metUpdateRecord = false;

            while select sum(AmountCur)
                from    _metCustVendAgingProcessingTmp
                    
                join    BucketNumber, Voucher
                from    _metCustVendAgingProcessingDetailsTmp
                    
                join    RecId
                from    metCustTrans
                
                group by _metCustVendAgingProcessingDetailsTmp.BucketNumber, _metCustVendAgingProcessingDetailsTmp.Voucher
                where   _metCustVendAgingProcessingDetailsTmp.ProcessingRecId   == _metCustVendAgingProcessingTmp.RecId
                &&      _metCustVendAgingProcessingDetailsTmp.Voucher           == metCustAgingReportTmp.Voucher
                &&      _metCustVendAgingProcessingTmp.AccountNum               == metCustAgingReportTmp.AccountNum
                &&      _metCustVendAgingProcessingTmp.TransRecId               == metCustTrans.RecId
                &&      metCustTrans.TransType                                  == LedgerTransType::Payment
            {
                metBalanceColumn = _metCustBalanceList.METGetBalanceColumn(_metCustVendAgingProcessingDetailsTmp.BucketNumber);

                switch(metBalanceColumn)
                {
                    case METBalanceColumn::Balance01 :
                        metCustAgingReportTmp.Balance01 = metCustAgingReportTmp.Balance01 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                    case METBalanceColumn::Balance02 :
                        metCustAgingReportTmp.Balance02 = metCustAgingReportTmp.Balance02 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                    case METBalanceColumn::Balance03 :
                        metCustAgingReportTmp.Balance03 = metCustAgingReportTmp.Balance03 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                    case METBalanceColumn::Balance04 :
                        metCustAgingReportTmp.Balance04 = metCustAgingReportTmp.Balance04 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                    case METBalanceColumn::Balance05 :
                        metCustAgingReportTmp.Balance05 = metCustAgingReportTmp.Balance05 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                    case METBalanceColumn::Balance06 :
                        metCustAgingReportTmp.Balance06 = metCustAgingReportTmp.Balance06 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                    case METBalanceColumn::Balance07 :
                        metCustAgingReportTmp.Balance07 = metCustAgingReportTmp.Balance07 - _metCustVendAgingProcessingTmp.AmountCur;
                        metCustAgingReportTmp.METUnallocatedCash = metCustAgingReportTmp.METUnallocatedCash + _metCustVendAgingProcessingTmp.AmountCur;
                        metUpdateRecord = true;
                        break;
                }
            }
                    
            if(metUpdateRecord)
            {
                metCustAgingReportTmp.update();
            }
        }
        ttscommit;
    }

    /// <summary>
    /// Processes the report business logic.
    /// </summary>
    /// <param name = "_metCustAgingReportTmp">original transaction buffer</param>
    public void metUpdateLegalDispute(CustAgingReportTmp _metCustAgingReportTmp)
    {
        CustAgingReportTmp          metCustAgingReportTmp = _metCustAgingReportTmp;
        METCustTableDisputeLegal    metCustTableDisputeLegal; //View
        //4.
        // MPJ-16249- Populate "Total Legal" column and reset other columns
        ttsbegin;
        
        update_recordset metCustAgingReportTmp
            setting
            METTotalInDisputeLegal  = metCustAgingReportTmp.METUnallocatedCash
                                    + metCustAgingReportTmp.Balance02
                                    + metCustAgingReportTmp.Balance03
                                    + metCustAgingReportTmp.Balance04
                                    + metCustAgingReportTmp.Balance05
                                    + metCustAgingReportTmp.Balance06
                                    + metCustAgingReportTmp.Balance07
        join metCustTableDisputeLegal
            where metCustTableDisputeLegal.AccountNum == metCustAgingReportTmp.AccountNum;
        
        ttscommit;

        ttsbegin;
        update_recordset metCustAgingReportTmp
            setting
            METUnallocatedCash      = 0,    //MPJ-23556 DCP 31/05/2022
            Balance02               = 0,
            Balance03               = 0,
            Balance04               = 0,
            Balance05               = 0,
            Balance06               = 0,
            Balance07               = 0
        join metCustTableDisputeLegal
            where metCustTableDisputeLegal.AccountNum == metCustAgingReportTmp.AccountNum;

        ttscommit;
    }

    /// <summary>
    /// Processes the report business logic.
    /// </summary>
    /// <param name = "_metCustAgingReportTmp">original transaction buffer</param>
    /// <param name = "_metCustBalanceList">Parameters</param>
    public void metUpdateOverDue(CustAgingReportTmp         _metCustAgingReportTmp,
                                 CustBalanceList             _metCustBalanceList)
    {
        CustAgingReportTmp  metCustAgingReportTmp = _metCustAgingReportTmp;
        //5. Update Total OverDue
        ttsbegin;

        if(_metCustBalanceList.METGetDirection() == ForwardBackwardPrinting::Backward)
        {
            update_recordset metCustAgingReportTmp
                setting
                METTotalOverDue = metCustAgingReportTmp.Balance03
                                + metCustAgingReportTmp.Balance04
                                + metCustAgingReportTmp.Balance05
                                + metCustAgingReportTmp.Balance06
                                + metCustAgingReportTmp.Balance07
                                + metCustAgingReportTmp.METTotalInDisputeLegal;
                
        }
        else
        {
            update_recordset metCustAgingReportTmp
                setting
                METTotalOverDue = metCustAgingReportTmp.Balance02
                                + metCustAgingReportTmp.METTotalInDisputeLegal;
        }
        
        ttscommit;

        //6. Update Total over Due %
        // MPJ-16249- New column OverDuePercentage
        ttsbegin;

        update_recordset metCustAgingReportTmp
            setting
            METTotalOverDuePercent = (metCustAgingReportTmp.METTotalOverDue / metCustAgingReportTmp.Balance01) * 100
            where metCustAgingReportTmp.Balance01 != 0;
        
        ttscommit;
    }

/// <summary>
/// Processes the report business logic.
/// </summary>
/// <param name = "_metCustAgingReportTmp">original transaction buffer</param>
public void metUpdateCreditLimit(CustAgingReportTmp _metCustAgingReportTmp)
{
    CustAgingReportTmp  metCustAgingReportTmp = _metCustAgingReportTmp;
    CustTable           custTable;
    //7.
    // MPJ-16249- New column creditlimit
    ttsbegin;
    
    update_recordset metCustAgingReportTmp
        setting
        METCreditLimit = custTable.CreditMax
    join CreditMax from custTable
        where custTable.AccountNum == metCustAgingReportTmp.AccountNum;
    
    ttscommit;
}
